#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum WallLocation {
    Left,
    Right,
    Bottom,
    Top,
}

impl std::fmt::Display for WallLocation {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "{:?}", self)
    }
}

impl WallLocation {
    pub fn position(&self) -> Point {
        match self {
            WallLocation::Left => {
                Point { x: LEFT_WALL, y: 0.0 }
            }
            WallLocation::Right => {
                Point { x: RIGHT_WALL, y: 0.0 }
            }
            WallLocation::Bottom => {
                Point { x: 0.0, y: BOTTOM_WALL }
            }
            WallLocation::Top => {
                Point { x: 0.0, y: TOP_WALL }
            }
        }
    }

    pub fn size(&self) -> Point {
        let arena_height = (TOP_WALL - BOTTOM_WALL);
        let arena_width = (RIGHT_WALL - LEFT_WALL);
        assert!((arena_height > 0.0));
        assert!((arena_width > 0.0));
        match self {
            WallLocation::Left => {
                Point { x: WALL_THICKNESS, y: (arena_height + WALL_THICKNESS) }
            }
            WallLocation::Right => {
                Point { x: WALL_THICKNESS, y: (arena_height + WALL_THICKNESS) }
            }
            WallLocation::Bottom => {
                Point { x: (arena_width + WALL_THICKNESS), y: WALL_THICKNESS }
            }
            WallLocation::Top => {
                Point { x: (arena_width + WALL_THICKNESS), y: WALL_THICKNESS }
            }
        }
    }

}

