pub fn move_by_velocity(pos: &Point, v: &Velocity, dt: f32) -> Point {
    Point { x: (pos.x + (v.x * dt)), y: (pos.y + (v.y * dt)) }
}

pub fn clamp_paddle_x(current_x: f32, direction: f32, speed: f32, dt: f32, left_bound: f32, right_bound: f32) -> f32 {
    let new_x = (current_x + ((direction * speed) * dt));
    (new_x).clamp(left_bound, right_bound)
}

pub fn ball_collision(ball_center: &Point, ball_radius: f32, box_center: &Point, box_half_size: &Point) -> Option<Collision> {
    let closest_x = (ball_center.x).clamp((box_center.x - box_half_size.x), (box_center.x + box_half_size.x));
    let closest_y = (ball_center.y).clamp((box_center.y - box_half_size.y), (box_center.y + box_half_size.y));
    let offset_x = (ball_center.x - closest_x);
    let offset_y = (ball_center.y - closest_y);
    let dist_sq = ((offset_x * offset_x) + (offset_y * offset_y));
    if (dist_sq > (ball_radius * ball_radius)) {
        return None;
    }
    if ((offset_x as f32).abs() > (offset_y as f32).abs()) {
        if (offset_x < 0.0) {
            return Some(Collision::Left);
        } else {
            return Some(Collision::Right);
        }
    } else {
        if (offset_y > 0.0) {
            return Some(Collision::Top);
        } else {
            return Some(Collision::Bottom);
        }
    }
}

pub fn reflect_velocity(v: &Velocity, c: Collision) -> Velocity {
    let mut reflect_x = false;
    let mut reflect_y = false;
    match c {
        Collision::Left => {
            reflect_x = (v.x > 0.0);
        }
        Collision::Right => {
            reflect_x = (v.x < 0.0);
        }
        Collision::Top => {
            reflect_y = (v.y < 0.0);
        }
        Collision::Bottom => {
            reflect_y = (v.y > 0.0);
        }
    }
    let nx =     match reflect_x {
        true => {
            (-v.x)
        }
        false => {
            v.x
        }
    };
    let ny =     match reflect_y {
        true => {
            (-v.y)
        }
        false => {
            v.y
        }
    };
    Velocity { x: nx, y: ny }
}

pub fn brick_layout(total_width: f32, total_height: f32, brick_w: f32, brick_h: f32, gap: f32, left_wall: f32, right_wall: f32, bricks_bottom_y: f32) -> BrickLayout {
    assert!((total_width > 0.0));
    assert!((total_height > 0.0));
    let n_columns = (((total_width / (brick_w + gap)) as f32).floor() as isize);
    let n_rows = (((total_height / (brick_h + gap)) as f32).floor() as isize);
    let n_vertical_gaps = (n_columns - 1);
    let center_x = ((left_wall + right_wall) / 2.0);
    let left_edge = ((center_x - (((n_columns as f32) / 2.0) * brick_w)) - (((n_vertical_gaps as f32) / 2.0) * gap));
    let offset_x = (left_edge + (brick_w / 2.0));
    let offset_y = (bricks_bottom_y + (brick_h / 2.0));
    BrickLayout { n_columns: n_columns, n_rows: n_rows, offset_x: offset_x, offset_y: offset_y }
}

pub fn brick_position(layout: &BrickLayout, row: isize, column: isize, brick_w: f32, brick_h: f32, gap: f32) -> Point {
    Point { x: (layout.offset_x + ((column as f32) * (brick_w + gap))), y: (layout.offset_y + ((row as f32) * (brick_h + gap))) }
}

pub fn wall_bundle(location: WallLocation) -> (Wall, Sprite, Transform) {
    let pos = location.position();
    let size = location.size();
    (Wall {}, Sprite::from_color(WALL_COLOR, Vec2::ONE), Transform { translation: Vec3::new(pos.x, pos.y, 0.0), scale: Vec3::new(size.x, size.y, 1.0), ..Default::default() })
}

pub fn spawn_camera(mut commands: Commands) -> () {
    commands.spawn(Camera2d);
}

pub fn set_clear_color(mut commands: Commands) -> () {
    commands.insert_resource(ClearColor(BACKGROUND_COLOR));
}

pub fn load_collision_sound(mut commands: Commands, asset_server: Res<AssetServer>) -> () {
    let handle = asset_server.load("sounds/breakout_collision.ogg");
    commands.insert_resource(CollisionSound { handle: handle });
}

pub fn spawn_paddle(mut commands: Commands) -> () {
    let paddle_y = (BOTTOM_WALL + GAP_BETWEEN_PADDLE_AND_FLOOR);
    commands.spawn((Sprite::from_color(PADDLE_COLOR, Vec2::ONE), Transform { translation: Vec3::new(0.0, paddle_y, 0.0), scale: PADDLE_SIZE.extend(1.0), ..Default::default() }, Paddle {}, Collider {}));
}

pub fn spawn_ball(mut commands: Commands, mut meshes: ResMut<Assets<Mesh>>, mut materials: ResMut<Assets<ColorMaterial>>) -> () {
    let initial_velocity = (INITIAL_BALL_DIRECTION.normalize() * BALL_SPEED);
    commands.spawn((Mesh2d(meshes.add(Circle::default())), MeshMaterial2d(materials.add(BALL_COLOR)), Transform::from_translation(BALL_STARTING_POSITION).with_scale(Vec2::splat(BALL_DIAMETER).extend(1.0)), Ball {}, Velocity { x: initial_velocity.x, y: initial_velocity.y }));
}

pub fn spawn_walls(mut commands: Commands) -> () {
    commands.spawn(wall_bundle(WallLocation::Left.clone()));
    commands.spawn(wall_bundle(WallLocation::Right.clone()));
    commands.spawn(wall_bundle(WallLocation::Bottom.clone()));
    commands.spawn(wall_bundle(WallLocation::Top.clone()));
}

pub fn spawn_bricks(mut commands: Commands) -> () {
    let paddle_y = (BOTTOM_WALL + GAP_BETWEEN_PADDLE_AND_FLOOR);
    let total_width_of_bricks = ((RIGHT_WALL - LEFT_WALL) - (2.0 * GAP_BETWEEN_BRICKS_AND_SIDES));
    let bottom_edge_of_bricks = (paddle_y + GAP_BETWEEN_PADDLE_AND_BRICKS);
    let total_height_of_bricks = ((TOP_WALL - bottom_edge_of_bricks) - GAP_BETWEEN_BRICKS_AND_CEILING);
    let layout = brick_layout(total_width_of_bricks, total_height_of_bricks, BRICK_SIZE.x.clone(), BRICK_SIZE.y.clone(), GAP_BETWEEN_BRICKS, LEFT_WALL, RIGHT_WALL, bottom_edge_of_bricks);
    for row in (0..layout.n_rows) {
        for column in (0..layout.n_columns) {
            let pos = brick_position(&layout, row, column, BRICK_SIZE.x.clone(), BRICK_SIZE.y.clone(), GAP_BETWEEN_BRICKS);
            commands.spawn((Sprite { color: BRICK_COLOR, ..Default::default() }, Transform { translation: Vec3::new(pos.x, pos.y, 0.0), scale: Vec3::new(BRICK_SIZE.x, BRICK_SIZE.y, 1.0), ..Default::default() }, Brick {}, Collider {}));
        }
    }
}

pub fn apply_velocity(query: Query<(&mut Transform, &Velocity)>, time: Res<Time>) -> () {
    let dt = time.delta_secs();
    for (mut transform, velocity) in query.into_iter() {
        let next = move_by_velocity(&Point { x: transform.translation.x, y: transform.translation.y }, &velocity, dt);
        transform.translation.x = next.x;
        transform.translation.y = next.y;
    }
}

pub fn move_paddle(keyboard_input: Res<ButtonInput<KeyCode>>, mut paddle_transform: Single<&mut Transform, With<Paddle>>, time: Res<Time>) -> () {
    let mut direction = 0.0;
    if keyboard_input.pressed(KeyCode::ArrowLeft) {
        direction -= 1.0;
    }
    if keyboard_input.pressed(KeyCode::ArrowRight) {
        direction += 1.0;
    }
    let left_bound = (((LEFT_WALL + (WALL_THICKNESS / 2.0)) + (PADDLE_SIZE.x / 2.0)) + PADDLE_PADDING);
    let right_bound = (((RIGHT_WALL - (WALL_THICKNESS / 2.0)) - (PADDLE_SIZE.x / 2.0)) - PADDLE_PADDING);
    let new_x = clamp_paddle_x(paddle_transform.translation.x.clone(), direction, PADDLE_SPEED, time.delta_secs(), left_bound, right_bound);
    paddle_transform.translation.x = new_x.clone();
}

pub fn check_for_collisions(mut commands: Commands, mut score: ResMut<Score>, mut ball_query: Single<(&mut Velocity, &Transform), With<Ball>>, collider_query: Query<(Entity, &Transform, Option<&Brick>), With<Collider>>) -> () {
    let mut ball = ball_query.into_inner();
    for (entity, collider_transform, maybe_brick) in collider_query.into_iter() {
        let maybe_collision = ball_collision(&Point { x: ball.1.translation.x, y: ball.1.translation.y }, (BALL_DIAMETER / 2.0), &Point { x: collider_transform.translation.x, y: collider_transform.translation.y }, &Point { x: (collider_transform.scale.x / 2.0), y: (collider_transform.scale.y / 2.0) });
        if let Some(collision) = maybe_collision {
            commands.trigger(BallCollided {});
            if maybe_brick.is_some() {
                commands.entity(entity).despawn();
                score.increment();
            }
            let reflected = reflect_velocity(&Velocity { x: ball.0.x, y: ball.0.y }, collision.clone());
            ball.0.x = reflected.x;
            ball.0.y = reflected.y;
        }
    }
}

pub fn play_collision_sound(collided: On<BallCollided>, mut commands: Commands, sound: Res<CollisionSound>) -> () {
    commands.spawn(AudioPlayer::new(sound.clone()));
}

const SCOREBOARD_FONT_SIZE: FontSize = FontSize::Px(33.0);

const SCOREBOARD_TEXT_PADDING: Val = Val::Px(5.0);

const TEXT_COLOR: Color = Color::srgb(0.5, 0.5, 1.0);

const SCORE_COLOR: Color = Color::srgb(1.0, 0.5, 0.5);

pub fn spawn_scoreboard_ui(mut commands: Commands) -> () {
    let mut root = commands.spawn((Text::new("Score: "), TextFont { font_size: SCOREBOARD_FONT_SIZE, ..Default::default() }, TextColor(TEXT_COLOR), ScoreboardUi {}, Node { position_type: PositionType::Absolute, top: SCOREBOARD_TEXT_PADDING, left: SCOREBOARD_TEXT_PADDING, ..Default::default() }));
    root.with_children(|parent| drop(parent.spawn((TextSpan::default(), TextFont { font_size: SCOREBOARD_FONT_SIZE, ..Default::default() }, TextColor(SCORE_COLOR)))));
}

pub fn update_scoreboard(score: Res<Score>, score_root: Single<Entity, (With<ScoreboardUi>, With<Text>)>, mut writer: TextUiWriter) -> () {
    *writer.text(*score_root, 1) = Arc::<str>::from(format!("{}", score.count).as_str()).to_string();
}

pub fn build_app() -> App {
    let mut app = App::new();
    app.add_plugins(DefaultPlugins);
    app.insert_resource(Score { count: 0 });
    app.add_systems(Startup, (set_clear_color, spawn_camera, load_collision_sound, spawn_paddle, spawn_ball, spawn_walls, spawn_bricks, spawn_scoreboard_ui));
    app.add_systems(Update, (apply_velocity, move_paddle, check_for_collisions).chain());
    app.add_systems(Update, update_scoreboard);
    app.add_observer(play_collision_sound);
    app
}

pub fn run_game() -> () {
    build_app().run();
}

fn main() -> () {
    run_game();
}

